157 | // Extract a single top-level `function NAME(...) { ... }` from a module source by brace-matching,
158 | // so a unit test can eval one helper without triggering the module's load-time panel builds.
159 | function extractFn(moduleName, fnName) {
160 |   const src = fs.readFileSync(path.join(SRC, moduleName), 'utf8');
161 |   const sig = 'function ' + fnName;
162 |   const start = src.indexOf(sig);
163 |   if (start < 0) throw new Error('function ' + fnName + ' not found in ' + moduleName);
164 |   // Naive brace count (no string/regex awareness): fine for small self-contained helpers whose only
165 |   // braces are structural. Do NOT use on functions that embed { or } inside a string or regex.
166 |   let i = src.indexOf('{', start), depth = 0;
167 |   for (; i < src.length; i++) {
168 |     const c = src[i];
169 |     if (c === '{') depth++;
170 |     else if (c === '}') { depth--; if (depth === 0) { i++; break; } }
171 |   }
172 |   return src.slice(start, i);
173 | }
