1 | /* Rules-based ranking engine — v0.3 (V2 Phase 1 + 2 + 3)
2 |  * Pure and dependency-free; runs in Node (tests) and the browser (inlined into the artifact).
3 |  *
4 |  *   scoreItem(metrics, ruleset)  ABSOLUTE per-item: typed scorers (+1/0/-1), weighted-averaged.
5 |  *   rankGroup(items, ruleset)    GROUP-RELATIVE: percentile-within-group (optional invert),
6 |  *                                grouped into dimensions, weighted-averaged.
7 |  *   validateRuleset(rs, names)   Structural validation for the editor / import.
8 |  *
9 |  * Weights: factors and dimensions may carry an optional numeric `weight` (default 1). With all
10 |  * weights at their default, weighted means equal plain means exactly — so baseline output is
11 |  * unchanged (guarded by the golden-master tests).
12 |  */
13 | (function (root, factory) {
14 |   var api = factory();
15 |   if (typeof module !== "undefined" && module.exports) module.exports = api;
16 |   else root.RankingEngine = api;
17 | })(typeof self !== "undefined" ? self : this, function () {
18 |   "use strict";
19 | 
20 |   function scLow(v, g, b)  { return v == null ? null : (v < g ? 1 : (v > b ? -1 : 0)); }
21 |   function scHigh(v, g, b) { return v == null ? null : (v > g ? 1 : (v < b ? -1 : 0)); }
22 |   function boolAbove(v, t) { return v == null ? null : (v > t ? 1 : 0); }
23 | 
24 |   function passesGate(gate, v) {
25 |     if (!gate) return true;
26 |     if (gate === "positiveEarnings") return v != null && v > 0;
27 |     if (gate === "notNull") return v != null;
28 |     return true;
29 |   }
30 | 
31 |   function factorScore(f, metrics) {
32 |     var v = metrics ? metrics[f.metric] : null;
33 |     if (v === undefined) v = null;
34 |     if (!passesGate(f.gate, v)) return null;
35 |     switch (f.type) {
36 |       case "low":       return scLow(v, f.good, f.bad);
37 |       case "high":      return scHigh(v, f.good, f.bad);
38 |       case "boolAbove": return boolAbove(v, f.threshold);
39 |       default:          return null;
40 |     }

