arguments.command:
# Load FMP_API_KEY from .env and test the server starts with the token arg
$envVars = @{}
Get-Content ".env" | Where-Object { $_ -match '^[^#].+=.' } | ForEach-Object {
  $parts = $_ -split '=', 2
  $envVars[$parts[0].Trim()] = $parts[1].Trim()
}
$fmpKey = $envVars['FMP_API_KEY']
if (-not $fmpKey) { Write-Host "FMP_API_KEY not found in .env"; exit 1 }
Write-Host "FMP_API_KEY found (${$fmpKey.Length} chars)"

# Start server with timeout — just check it launches without error
$proc = Start-Process -FilePath "npx" -ArgumentList "financial-modeling-prep-mcp-server --fmp-token=$fmpKey" -PassThru -NoNewWindow -RedirectStandardOutput "$env:TEMP\fmp_out.txt" -RedirectStandardError "$env:TEMP\fmp_err.txt"
Start-Sleep -Seconds 5
if (-not $proc.HasExited) {
  Write-Host "Server is running (PID $($proc.Id)) — stopping"
  $proc.Kill()
  Get-Content "$env:TEMP\fmp_out.txt" -ErrorAction SilentlyContinue | Select-Object -First 5
} else {
  Write-Host "Server exited with code $($proc.ExitCode)"
  Get-Content "$env:TEMP\fmp_err.txt" -ErrorAction SilentlyContinue | Select-Object -First 10
}

